import { useCallback, useEffect, useRef, useState } from 'react';

import { useLazyMount } from './LazyMountContext';

const PLACEHOLDER_HEIGHT = 938;
const PLACEHOLDER_WIDTH = 1668;

interface LazySlideProps {
  children: React.ReactNode;
  id: string;
  estimatedHeight?: number;
}

export const LazySlide = ({
  children,
  id,
  estimatedHeight = PLACEHOLDER_HEIGHT,
}: LazySlideProps) => {
  const [mounted, setMounted] = useState(
    () => typeof IntersectionObserver === 'undefined',
  );
  const ref = useRef<HTMLDivElement>(null);
  const { register, unregister, observe } = useLazyMount();

  const mount = useCallback(() => setMounted(true), []);

  useEffect(() => {
    register(id, mount);
    return () => unregister(id);
  }, [id, mount, register, unregister]);

  useEffect(() => {
    if (mounted || !ref.current) return;
    observe(id, ref.current);
  }, [id, mounted, observe]);

  if (!mounted) {
    return (
      <div
        ref={ref}
        data-page-name={id}
        data-lazy-placeholder=""
        style={{
          height: `${estimatedHeight}px`,
          width: `${PLACEHOLDER_WIDTH}px`,
        }}
      />
    );
  }

  return <>{children}</>;
};
